  @case 'tracksTakes relayouts on read: an OPEN take grows to its source length'  [harness]  @ 801-810
  @case 'build relayout: OPEN takes fill to source; an earlier one capped at its gap (no overlap)'  [harness]  @ 813-824
  @case 'build relayout: an OPEN take whose item outruns its shrunk source is pulled back'  [harness]  @ 827-835
  @case 'a later take truncates an earlier one; deleting the later regrows it'  [harness]  @ 839-853
  @case 'resizeTake stores a numeric natural; ≥ source demotes back to util.OPEN'  [harness]  @ 857-873
  @case 'audio take longer than its source keeps its length across a move'  [harness]  @ 876-891
