  @case 'the lower half inherits the natural, so the pair ends where the whole did'  [harness]  @ 1053-1065
  @case 'splitting a head-trimmed take leaves both halves on the source origin'  [harness]  @ 1068-1082
  @case 'a split is refused on either edge, off the take, and on audio'  [harness]  @ 1085-1098
  @case 'deleteTake removes the item, leaving the other take intact'  [harness]  @ 1102-1113
